def step(state, rng):
    if rng.random() < 0.04176572901661965:
        dt = rng.lognormvariate(-0.13577801211836546, 0.5)
    else:
        dt = rng.lognormvariate(3.7948770260146185, 1.2036090208705792)
    dt = max(dt, 0.001)
    group = rng.choices(['optimism'], weights=[1.0])[0]
    kind = rng.choices(['GnosisSafeProxy'], weights=[1.0])[0]
    return {'dt_hours': dt, 'group': group, 'kind': kind}
